import subprocess
import sys
import json
import time
from pathlib import Path

def run_repo_tests(repo_path: str, test_path: str='tests', timeout: int=300) -> dict:
    root = Path(repo_path)
    if not root.is_dir():
        return {'ok': False, 'error': f'{repo_path} is not a directory'}
    target = root / test_path
    if not target.exists():
        return {'ok': False, 'error': f'{test_path} not found'}
    try:
        proc = subprocess.run([sys.executable, '-m', 'pytest', str(target), '-q', '--tb=short'], cwd=str(root), capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return {'ok': False, 'error': f'timed out after {timeout}s'}
    lines = proc.stdout.strip().splitlines()
    result = {'ok': True, 'exit_code': proc.returncode, 'passed': proc.returncode == 0, 'summary': lines[-1] if lines else '', 'output_tail': '\n'.join(lines[-20:]), 'stderr': proc.stderr.strip()[-500:]}
    # Record the latest run result in a status file inside the repository
    record = {'timestamp': time.time(), 'test_path': test_path, 'exit_code': proc.returncode, 'summary': result['summary']}
    (root / '.last_test_run.json').write_text(json.dumps(record, indent=2))
    return result
